import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const m=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"source":"resources/glossary.md"},"headers":[],"relativePath":"resources/glossary.md","filePath":"resources/glossary.md"}'),s={name:"resources/glossary.md"};function n(i,e,h,l,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><blockquote><p>Plain-English definitions of every technical word the course uses. Each entry says which week teaches it. Don&#39;t read this page top to bottom. Look words up when you meet them, then come back to what you were doing. Entries marked <em>Week 0</em> are JavaScript terms introduced in <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>, for anyone who knows Python (or another language) but not JavaScript.</p></blockquote><p><strong>Jump to:</strong> <a href="#a">A</a> · <a href="#b">B</a> · <a href="#c">C</a> · <a href="#d">D</a> · <a href="#e">E</a> · <a href="#f">F</a> · <a href="#g">G</a> · <a href="#h">H</a> · <a href="#i">I</a> · <a href="#j">J</a> · <a href="#k">K</a> · <a href="#l">L</a> · <a href="#m">M</a> · <a href="#n">N</a> · <a href="#o">O</a> · <a href="#p">P</a> · <a href="#r">R</a> · <a href="#s">S</a> · <a href="#t">T</a> · <a href="#u">U</a> · <a href="#v">V</a> · <a href="#w">W</a> · <a href="#x">X</a></p><p><strong>Weeks:</strong> <a href="./../setup/">0 Pre-work</a> · <a href="./../weeks/01-hello-vibe-coding/">1 Hello, Vibe Coding</a> · <a href="./../weeks/02-ship-your-page/">2 Ship Your Page</a> · <a href="./../weeks/03-prompting-and-save-points/">3 Prompting &amp; Save Points</a> · <a href="./../weeks/04-undo-compare-explain/">4 Undo, Compare, Explain</a> · <a href="./../weeks/05-spec-first/">5 Spec First</a> · <a href="./../weeks/06-spec-to-app/">6 From Spec to App</a> · <a href="./../weeks/07-read-and-debug/">7 Read It, Debug It</a> · <a href="./../weeks/08-own-it/">8 Own It</a> · <a href="./../weeks/09-apis-and-secrets/">9 APIs &amp; Secrets</a> · <a href="./../weeks/10-servers-and-deployment/">10 Servers &amp; Deployment</a> · <a href="./../weeks/11-agents/">11 How Agents Work</a> · <a href="./../weeks/12-pull-requests/">12 Pull Requests &amp; Agent Code</a> · <a href="./../weeks/13-data-and-access/">13 Data &amp; Access Rules</a> · <a href="./../weeks/14-security-and-review/">14 Security &amp; Review</a> · <a href="./../weeks/15-ship-it/">15 Ship It</a> · <a href="./../weeks/16-final-presentations/">16 Final Presentations</a></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Tool names appear here only when you use them every week. Limits, prices and model names live in <a href="./../TOOLS.html">Tool Handout</a>, because they change every month.</p></div><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="acceptance-criterion" tabindex="-1">Acceptance criterion <a class="header-anchor" href="#acceptance-criterion" aria-label="Permalink to &quot;Acceptance criterion&quot;">​</a></h3><p>One checkable sentence that says what the app must do in one situation, written as <strong>WHEN</strong> <em>situation</em>, <strong>THE APP SHALL</strong> <em>result</em>. It tells you, and the AI, when a feature is done. <em>Like a building inspector&#39;s checklist: each line passes or fails, no opinions.</em> Plural: acceptance criteria. See <a href="#ears">EARS</a> and <a href="./../templates/SPEC.html">SPEC.md template</a>. <em>Week 5.</em></p><h3 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h3><p>Making your app usable by everyone, including people who use a screen reader, navigate with a keyboard, or see colors differently. The basics: text alternatives (<code>alt</code> text) for images, enough contrast between text and background, real buttons and headings in the HTML, and everything reachable with the keyboard. Using the course&#39;s own tools with a screen reader or keyboard: <a href="./accessibility.html">Screen Reader and Keyboard Guide</a>. <em>Weeks 2 and 15.</em></p><h3 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>An <a href="#llm">LLM</a> in a loop with tools. It reads files, edits them, runs commands, looks at the result and decides its next step, again and again until the task is done or it gets stuck. <em>Like a very fast new intern with keys to your workshop: useful, eager, and needs clear instructions and checking.</em> <em>Week 11.</em></p><h3 id="agentic-engineering" tabindex="-1">Agentic engineering <a class="header-anchor" href="#agentic-engineering" aria-label="Permalink to &quot;Agentic engineering&quot;">​</a></h3><p>The professional way to build serious software with <a href="#agent">agents</a>: the AI writes and runs code, but humans stay responsible for the plan, the quality, the security and understanding the result. Andrej Karpathy used the term in 2026 for the discipline that grew out of <a href="#vibe-coding">vibe coding</a>. <em>Weeks 1 and 11.</em></p><h3 id="agent-mode" tabindex="-1">Agent mode <a class="header-anchor" href="#agent-mode" aria-label="Permalink to &quot;Agent mode&quot;">​</a></h3><p>The setting in an editor assistant such as Copilot where the AI acts as an <a href="#agent">agent</a>: it edits files and runs commands itself, asking for your approval along the way. It uses far more credits than <a href="#ask-mode">Ask mode</a>. <em>Week 11.</em></p><h3 id="agent-skill" tabindex="-1">Agent skill <a class="header-anchor" href="#agent-skill" aria-label="Permalink to &quot;Agent skill&quot;">​</a></h3><p>A folder of instructions for an agent, built around a <code>SKILL.md</code> file and sometimes scripts, that the agent loads by itself when a task matches the skill&#39;s description, such as &quot;how to deploy this project&quot;. Skills follow an open standard, so one skill works in many agents. A skill can make the agent do anything the agent is allowed to do, and attackers publish harmful ones, so read a skill before you add it (<a href="./../setup/safety-contract.html">safety contract rule 7</a>; <a href="./case-studies.html#14-pixelleak-agents-publish-13000-screenshots">case studies 14 and B</a>). <em>Week 11.</em></p><h3 id="agentsmd" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agentsmd" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h3><p>A file in the top folder of a repository that gives AI agents standing instructions: what the project is, which commands to run, what never to do. <em>A README written for agents.</em> Read any AGENTS.md you copy from the internet before using it, because hidden instructions can be planted in it. Its <strong>Scope</strong> section lists the folders the agent may change and what it must ask about first. It is <em>advice</em>, not enforcement: an agent can ignore it, so the real protection comes from the Codespace, approval prompts, <a href="#scoped-token">scoped tokens</a>, <a href="#spending-cap">spending caps</a> and row-level security. Template: <a href="./../templates/AGENTS.html">AGENTS.md template</a>. <em>Week 11.</em></p><h3 id="ai-credits" tabindex="-1">AI credits <a class="header-anchor" href="#ai-credits" aria-label="Permalink to &quot;AI credits&quot;">​</a></h3><p>The usage allowance some tools, such as GitHub Copilot, give you each month. Every AI answer spends some. When they run out, the AI features stop until the allowance resets, so switch to a fallback tool. Current allowances are in <a href="./../TOOLS.html">Tool Handout</a>. See <a href="./troubleshooting.html#i-ran-out-of-free-credits">troubleshooting</a>. <em>Weeks 7–16.</em></p><h3 id="ai-journal" tabindex="-1">AI journal <a class="header-anchor" href="#ai-journal" aria-label="Permalink to &quot;AI journal&quot;">​</a></h3><p>Your private notes, week by week, on how you are using AI and what you are learning from it, kept on <a href="#canvas-lms">Canvas</a> and never in a repository. Unlike <code>PROMPTS.md</code>, which is a public log of one project&#39;s key prompts, the journal is personal writing; your weekly reflection draws on it. <em>Week 1 onward.</em></p><h3 id="alt-text" tabindex="-1">Alt text <a class="header-anchor" href="#alt-text" aria-label="Permalink to &quot;Alt text&quot;">​</a></h3><p>A short description of an image, written in the HTML <code>alt</code> attribute: <code>&lt;img src=&quot;cat.jpg&quot; alt=&quot;A gray cat asleep on a keyboard&quot;&gt;</code>. Screen readers read it aloud, and browsers show it if the image fails to load. See <a href="#accessibility">accessibility</a>. <em>Weeks 2 and 15.</em></p><h3 id="anon-key" tabindex="-1">Anon key <a class="header-anchor" href="#anon-key" aria-label="Permalink to &quot;Anon key&quot;">​</a></h3><p>Supabase&#39;s legacy public key (a long key starting <code>eyJ</code>), replaced by the <a href="#publishable-key">publishable key</a> and deprecated by the end of 2026. If a tutorial or an AI tells you to use it, use the publishable key instead.</p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>Short for <em>application programming interface</em>: a set of requests one program can make to another, and the answers it sends back. Your app uses an LLM provider&#39;s API to get AI replies. <em>Like a restaurant menu plus a waiter: you order from a fixed list and something comes back from a kitchen you never see.</em> See <a href="./web-basics.html#apis">How the Web Works: APIs</a>. <em>Week 9.</em></p><h3 id="api-key" tabindex="-1">API key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API key&quot;">​</a></h3><p>A secret string that identifies you to an <a href="#api">API</a>, so the provider knows whom to bill and limit. Treat it exactly like a password: keep it on the <a href="#server">server</a>, in an <a href="#environment-variable">environment variable</a>, and never put it in browser code, in git or in an AI chat. <em>Week 9.</em></p><h3 id="app-builder" tabindex="-1">App builder <a class="header-anchor" href="#app-builder" aria-label="Permalink to &quot;App builder&quot;">​</a></h3><p>A browser tool that generates a whole working app from a description, for example Google AI Studio <em>Build</em>, Bolt, Lovable, v0 or Replit. Fast for a first version, but the code lives on their platform until you export it to GitHub. <em>Week 6.</em></p><h3 id="array" tabindex="-1">Array <a class="header-anchor" href="#array" aria-label="Permalink to &quot;Array&quot;">​</a></h3><p>JavaScript&#39;s version of a Python list, written in square brackets: <code>[&quot;milk&quot;, &quot;eggs&quot;, &quot;bread&quot;]</code>. Many operations have new names: <code>items.length</code> for <code>len(items)</code>, <code>items.push(x)</code> for <code>items.append(x)</code>, <code>items.includes(x)</code> for <code>x in items</code>. Watch out: <code>sort()</code> sorts as text unless you give it a comparison, and <code>items[-1]</code> is <a href="#undefined">undefined</a> (use <code>items.at(-1)</code>). See <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward.</em></p><h3 id="arrow-function" tabindex="-1">Arrow function <a class="header-anchor" href="#arrow-function" aria-label="Permalink to &quot;Arrow function&quot;">​</a></h3><p>A shorter way to write a JavaScript <a href="#function">function</a>: <code>(x) =&gt; x * 2</code> takes <code>x</code> and returns <code>x * 2</code>. Like Python&#39;s <code>lambda</code>, but it can also have a full body in braces, and then it needs its own <code>return</code>: <code>(x) =&gt; { return x * 2; }</code>. AI-written code uses arrow functions everywhere, especially for <a href="#callback">callbacks</a>. See <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward.</em></p><h3 id="ask-mode" tabindex="-1">Ask mode <a class="header-anchor" href="#ask-mode" aria-label="Permalink to &quot;Ask mode&quot;">​</a></h3><p>The setting in an editor assistant such as Copilot where the AI only answers questions and suggests code in the chat; it doesn&#39;t change your files. The mode used in weeks 7–8, when <em>you</em> write the code. Compare <a href="#agent-mode">agent mode</a>. <em>Week 7.</em></p><h3 id="assisted-by-line" tabindex="-1">Assisted-by line <a class="header-anchor" href="#assisted-by-line" aria-label="Permalink to &quot;Assisted-by line&quot;">​</a></h3><p>A line at the end of a commit message, after a blank line, that names the AI tool that helped, such as <code>Assisted-by: GitHub Copilot</code>. Many open-source projects ask for the same line. How to add it: <a href="./safe-loop.html#the-assisted-by-line">The Safe Loop: The Assisted-by line</a>. <em>Taught in week 3; required on AI-assisted commits from week 11.</em></p><h3 id="async-and-await" tabindex="-1">async and await <a class="header-anchor" href="#async-and-await" aria-label="Permalink to &quot;async and await&quot;">​</a></h3><p>JavaScript words for code that has to wait, such as a request to a server. <code>await</code> pauses that function until the answer arrives, without freezing the whole page; a function that uses <code>await</code> must be marked <code>async</code>. Unlike Python&#39;s <code>requests.get()</code>, which simply waits, <code>fetch</code> hands back a <a href="#promise">Promise</a> at once; forget the <code>await</code> and you get the Promise instead of the data. <em>Week 0; used from week 9.</em></p><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>Proving <strong>who you are</strong>, usually by logging in. <em>Showing your ID at the front desk.</em> Compare <a href="#authorization">authorization</a>. <em>Week 13.</em></p><h3 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h3><p>Deciding <strong>what you are allowed to do</strong> once the app knows who you are (or knows you&#39;re anonymous). <em>Your ID gets you into the building; authorization decides which rooms your key card opens.</em> It must be enforced on the server or in the database, for example with <a href="#row-level-security-rls">row-level security</a>. Hiding a button in the browser is not authorization. <em>Week 13.</em></p><h3 id="autopilot-mode" tabindex="-1">Autopilot mode <a class="header-anchor" href="#autopilot-mode" aria-label="Permalink to &quot;Autopilot mode&quot;">​</a></h3><p>A setting in some agents that lets them carry out a whole task without asking you to approve each step. Other tools call it &quot;skip-permissions&quot;, &quot;full auto&quot; or &quot;YOLO&quot; mode. <strong>Never use it in this course.</strong> An agent in autopilot that reads untrusted content, such as a web page, can be steered into sending your secrets away before you can stop it (<a href="./case-studies.html#c-autopilot-a-web-page-that-sent-secrets-away">case study C</a>; <a href="./../setup/safety-contract.html">safety contract rule 9</a>). Keep approvals on. <em>Week 11.</em></p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="back-end" tabindex="-1">Back end <a class="header-anchor" href="#back-end" aria-label="Permalink to &quot;Back end&quot;">​</a></h3><p>The parts of an app that run on a <a href="#server">server</a>, out of the public&#39;s sight: server routes, the database, and the secrets. Compare <a href="#front-end">front end</a>. <em>Week 9.</em></p><h3 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h3><p>The start of a web API&#39;s address, which every request builds on, such as <code>https://api.groq.com/openai/v1</code>. In the week 9 starter it is the <code>LLM_BASE_URL</code> setting: change it, the key and the model ID, and you have switched AI provider without touching code (the week 10 provider-swap drill). <em>Weeks 9–10.</em></p><h3 id="branch" tabindex="-1">Branch <a class="header-anchor" href="#branch" aria-label="Permalink to &quot;Branch&quot;">​</a></h3><p>A separate line of <a href="#commit">commits</a> where you can try something without touching your main version. When it works, you <a href="#merge">merge</a> it back, usually through a <a href="#pull-request">pull request</a>. <em>Like photocopying a draft so you can scribble on the copy.</em> <em>Week 12.</em></p><h3 id="branch-protection" tabindex="-1">Branch protection <a class="header-anchor" href="#branch-protection" aria-label="Permalink to &quot;Branch protection&quot;">​</a></h3><p>A GitHub repository setting that guards a <a href="#branch">branch</a>, usually <code>main</code>. GitHub&#39;s newer version is called a <em>ruleset</em>. A typical rule: nothing reaches <code>main</code> except through a <a href="#pull-request">pull request</a>, and nobody, including an agent, can push straight to it or overwrite its history. It is real enforcement, unlike a line in <code>AGENTS.md</code>. How: <a href="./git-cheatsheet.html#branches-and-pull-requests">Git Cheat Sheet: Branches and pull requests</a>. <em>Week 12.</em></p><h3 id="breakpoint" tabindex="-1">Breakpoint <a class="header-anchor" href="#breakpoint" aria-label="Permalink to &quot;Breakpoint&quot;">​</a></h3><p>A marker you set on a line of code, in DevTools → Sources, that pauses the program when it reaches that line. While it&#39;s paused you can look at the value of every variable. Optional, but a powerful debugging tool. <em>Week 7.</em></p><h3 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser&quot;">​</a></h3><p>The program that fetches web pages and runs their HTML, CSS and JavaScript: Chrome, Edge, Firefox, Safari. Everything the browser receives, the person using it can inspect with <a href="#devtools">DevTools</a>. <em>Week 1.</em></p><h3 id="build-step" tabindex="-1">Build step <a class="header-anchor" href="#build-step" aria-label="Permalink to &quot;Build step&quot;">​</a></h3><p>An extra stage some projects need before a browser can run them, where a tool converts and bundles the code. It is common with <a href="#framework">frameworks</a>. This course&#39;s projects have no build step, so the files you write are exactly what the browser runs. <em>Week 5.</em></p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="cache" tabindex="-1">Cache <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;Cache&quot;">​</a></h3><p>Copies of files that your browser keeps so pages load faster. Sometimes it shows you an old version of your site after you&#39;ve changed it. A <a href="#hard-reload">hard reload</a> fixes that. <em>Weeks 1–8.</em></p><h3 id="callback" tabindex="-1">Callback <a class="header-anchor" href="#callback" aria-label="Permalink to &quot;Callback&quot;">​</a></h3><p>A function you hand to other code to call later, instead of calling it yourself. <code>button.addEventListener(&quot;click&quot;, addBook)</code> passes <code>addBook</code> as a callback, and the browser calls it on every click. Python&#39;s <code>sorted(words, key=len)</code> does the same with <code>len</code>. See <a href="#event-and-event-listener">event and event listener</a>. <em>Week 0 onward.</em></p><h3 id="canvas-lms" tabindex="-1">Canvas (LMS) <a class="header-anchor" href="#canvas-lms" aria-label="Permalink to &quot;Canvas (LMS)&quot;">​</a></h3><p><strong>Canvas, the course&#39;s learning management system</strong> (<a href="#lms">LMS</a>): the private course website where you submit graded personal writing (reflections, your <a href="#ai-journal">AI journal</a>, exit tickets, the signed safety contract, written peer reviews) and see your grades. It has nothing to do with Gemini&#39;s Canvas, a <a href="#live-preview">live preview</a> panel, or with the HTML <a href="#canvas-element">canvas element</a>. <em>Week 0 onward.</em></p><h3 id="canvas-element" tabindex="-1">Canvas element <a class="header-anchor" href="#canvas-element" aria-label="Permalink to &quot;Canvas element&quot;">​</a></h3><p><code>&lt;canvas&gt;</code>: an HTML element that JavaScript can draw on, pixel by pixel. Most browser games use one. Not the same thing as Gemini&#39;s Canvas, which is a <a href="#live-preview">live preview</a> panel, or the course&#39;s <a href="#canvas-lms">Canvas</a> website. <em>Week 3.</em></p><h3 id="cdn" tabindex="-1">CDN <a class="header-anchor" href="#cdn" aria-label="Permalink to &quot;CDN&quot;">​</a></h3><p>Short for <em>content delivery network</em>: servers around the world that hand out copies of the same files, so each visitor gets them from somewhere nearby. Public CDNs such as jsDelivr also host code libraries that a page can load with one <code>import</code> line; the week 13 database code loads the Supabase library this way. Code from a CDN runs with full power inside your page, so load only libraries your plan names, and pin the version. See <a href="./web-basics.html#cdns-code-from-someone-elses-server">How the Web Works: CDNs: code from someone else&#39;s server</a>. <em>Week 13.</em></p><h3 id="check-first" tabindex="-1">Check first <a class="header-anchor" href="#check-first" aria-label="Permalink to &quot;Check first&quot;">​</a></h3><p>The Safe Loop habit of writing the check for a change <em>before</em> asking the AI for the code, in a separate prompt: the &quot;done when&quot; list and, from week 6 where the logic allows it, an automated test. Tests written after faulty code tend to agree with the faults. See <a href="./safe-loop.html#check-first">The Safe Loop: Check first</a>. <em>Week 3 onward; as an automated test from week 6.</em></p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>Short for <em>command-line interface</em>: a program you use by typing commands in a <a href="#terminal">terminal</a> instead of clicking. git, npm and Copilot CLI are all CLIs. <em>Weeks 4–11.</em></p><h3 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h3><p>The side of a conversation that asks for something, usually the <a href="#browser">browser</a>. Anything sent to the client is public. Compare <a href="#server">server</a>. <em>Week 9.</em></p><h3 id="clone" tabindex="-1">Clone <a class="header-anchor" href="#clone" aria-label="Permalink to &quot;Clone&quot;">​</a></h3><p>To download a complete copy of a repository, including its history, with <code>git clone [address]</code>. A Codespace does this for you. You only need it for the optional <a href="./../setup/local-setup.html">local setup</a>.</p><h3 id="codespace" tabindex="-1">Codespace <a class="header-anchor" href="#codespace" aria-label="Permalink to &quot;Codespace&quot;">​</a></h3><p>A cloud computer from GitHub that runs VS Code in your browser, attached to one repository. You first open one in week 4; it is the course&#39;s main workspace from week 6 and the <a href="#sandbox">sandbox</a> for agents. Free hours are listed in <a href="./../TOOLS.html">Tool Handout</a>; stop it when you finish. <em>Weeks 4 and 6.</em></p><h3 id="command-palette" tabindex="-1">Command Palette <a class="header-anchor" href="#command-palette" aria-label="Permalink to &quot;Command Palette&quot;">​</a></h3><p>VS Code&#39;s search box for every command: press <strong>Ctrl+Shift+P</strong> (Windows, Linux, ChromeOS) or <strong>Cmd+Shift+P</strong> (Mac) and start typing what you want, such as &quot;Reload Window&quot;. Useful when you can&#39;t find a menu. <em>Week 4.</em></p><h3 id="commit" tabindex="-1">Commit <a class="header-anchor" href="#commit" aria-label="Permalink to &quot;Commit&quot;">​</a></h3><p>A saved snapshot of your project with a short message saying what changed, such as <code>Add dark mode toggle</code>. <em>A save point in a video game: if the next level goes badly, you reload from here.</em> See <a href="./git-cheatsheet.html">Git Cheat Sheet</a>. <em>Weeks 2–4.</em></p><h3 id="commit-hash" tabindex="-1">Commit hash <a class="header-anchor" href="#commit-hash" aria-label="Permalink to &quot;Commit hash&quot;">​</a></h3><p>The unique ID of a <a href="#commit">commit</a>: a long string of letters and numbers such as <code>3f9c2ab…</code>. The first seven characters are usually enough to point at one exact save point. Also called a <em>SHA</em>. <em>Week 3.</em></p><h3 id="completions" tabindex="-1">Completions <a class="header-anchor" href="#completions" aria-label="Permalink to &quot;Completions&quot;">​</a></h3><p>Gray &quot;ghost text&quot; that an editor assistant suggests as you type. Press Tab to accept, keep typing to ignore. Also called inline suggestions. They are switched off for the <a href="#debug-clinic">Debug Clinic</a>. <em>Week 7.</em></p><h3 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h3><p>The <a href="#devtools">DevTools</a> tab that shows error messages and notes from JavaScript. Red lines are errors, with the file name and line number. You can also type JavaScript there to try things, as in <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward; for debugging, week 7.</em></p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>How much text a <a href="#model">model</a> can &quot;see&quot; at once: your messages, its replies, pasted files and hidden instructions, all counted in <a href="#token">tokens</a>. When it fills up, older parts get squeezed out and answers get worse, which is why long, muddled chats go wrong. <em>Like a desk: only so much paper fits, and when you pile it high things slide off the back.</em> <em>Weeks 1 and 11.</em></p><h3 id="copilot" tabindex="-1">Copilot <a class="header-anchor" href="#copilot" aria-label="Permalink to &quot;Copilot&quot;">​</a></h3><p>GitHub&#39;s AI assistant inside VS Code: code completions, a chat panel (Ask mode), agent mode, and a command-line agent (Copilot CLI). The course&#39;s primary editor assistant from week 7, and its agent from week 11. Plans and limits: <a href="./../TOOLS.html">Tool Handout</a>. <em>Weeks 7–16.</em></p><h3 id="css" tabindex="-1">CSS <a class="header-anchor" href="#css" aria-label="Permalink to &quot;CSS&quot;">​</a></h3><p>Short for <em>Cascading Style Sheets</em>: the language that says how a page looks, including colors, fonts, spacing and layout. <em>If HTML is the walls of a house, CSS is the paint and furniture.</em> <em>Week 1.</em></p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h3><p>Organized storage for data that lives on a server and that many users share. <em>Like a shared spreadsheet with strict rules about who may read and change each row.</em> The course uses Supabase from week 13. See <a href="#row-level-security-rls">row-level security</a>. <em>Week 13.</em></p><h3 id="debug-clinic" tabindex="-1">Debug Clinic <a class="header-anchor" href="#debug-clinic" aria-label="Permalink to &quot;Debug Clinic&quot;">​</a></h3><p>The week 7 activity where you find and fix planted bugs with the AI switched off, using error messages, <a href="#devtools">DevTools</a> and reading. It exists because debugging is the skill that AI help erodes most. <em>Week 7.</em></p><h3 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h3><p>A short list of what must be true before you call a project finished, for example: it works at the live URL, the tests pass, the README is complete, the security checklist has evidence. It stops &quot;done&quot; from meaning &quot;it worked once on my screen&quot;. <em>Week 15.</em></p><h3 id="degit" tabindex="-1">degit <a class="header-anchor" href="#degit" aria-label="Permalink to &quot;degit&quot;">​</a></h3><p>A small tool, run with <a href="#npx">npx</a>, that copies a GitHub repository&#39;s files without its history. The course uses it as the fallback way to <a href="./../setup/codespaces.html#start-a-project-from-a-starter">start a project from a starter kit</a>. <em>Weeks 7–11.</em></p><h3 id="dependency" tabindex="-1">Dependency <a class="header-anchor" href="#dependency" aria-label="Permalink to &quot;Dependency&quot;">​</a></h3><p>See <a href="#package">package</a>.</p><h3 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h3><p>To put your app on the internet at a public address so anyone can open it. The company that serves it is the <em>host</em> (GitHub Pages, Vercel). <em>Weeks 2 and 10.</em></p><h3 id="devtools" tabindex="-1">DevTools <a class="header-anchor" href="#devtools" aria-label="Permalink to &quot;DevTools&quot;">​</a></h3><p>The developer tools built into every desktop browser. Open them with <strong>F12</strong>, or <strong>Ctrl+Shift+I</strong> (Windows, Linux, ChromeOS) or <strong>Cmd+Option+I</strong> (Mac). The main tabs are Elements, Console, Network, Sources and Application. Tour: <a href="./web-basics.html#a-short-devtools-tour">How the Web Works: A short DevTools tour</a>. <em>Week 0 onward; in depth in week 7.</em></p><h3 id="diff" tabindex="-1">Diff <a class="header-anchor" href="#diff" aria-label="Permalink to &quot;Diff&quot;">​</a></h3><p>A view of exactly what changed between two versions of a file: removed lines in red (marked <code>-</code>), added lines in green (marked <code>+</code>). <em>Like &quot;track changes&quot; in a word processor.</em> Reading the diff is step 5 of <a href="#safe-loop">the Safe Loop</a>. <em>Week 3.</em></p><h3 id="dom" tabindex="-1">DOM <a class="header-anchor" href="#dom" aria-label="Permalink to &quot;DOM&quot;">​</a></h3><p>Short for <em>Document Object Model</em>: the browser&#39;s live, in-memory version of your page, built from your HTML. JavaScript changes what you see by changing the DOM. <em>HTML is the blueprint; the DOM is the building as it stands right now, remodeling included.</em> The Elements tab in DevTools shows it. <em>Week 0 onward; in depth in week 7.</em></p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="ears" tabindex="-1">EARS <a class="header-anchor" href="#ears" aria-label="Permalink to &quot;EARS&quot;">​</a></h3><p>Short for <em>Easy Approach to Requirements Syntax</em>: a way of writing requirements as <strong>WHEN</strong> <em>something happens</em>, <strong>THE SYSTEM SHALL</strong> <em>do something</em>. Anyone can learn it in minutes, programmer or not. This course uses the form <strong>WHEN … THE APP SHALL …</strong> for <a href="#acceptance-criterion">acceptance criteria</a>. <em>Week 5.</em></p><h3 id="edge-case" tabindex="-1">Edge case <a class="header-anchor" href="#edge-case" aria-label="Permalink to &quot;Edge case&quot;">​</a></h3><p>An unusual but possible situation: an empty box, very long text, a duplicate, reloading the page, a tiny phone screen, no internet. AI-written code usually handles the normal case and breaks on edge cases, so you test them on purpose. <em>Weeks 5–8.</em></p><h3 id="eea" tabindex="-1">EEA <a class="header-anchor" href="#eea" aria-label="Permalink to &quot;EEA&quot;">​</a></h3><p>The European Economic Area: the EU countries plus Iceland, Liechtenstein and Norway. Some free AI tiers may not be used to serve people there, or in the UK and Switzerland. Your instructor has an adjusted tool list for these cohorts.</p><h3 id="element" tabindex="-1">Element <a class="header-anchor" href="#element" aria-label="Permalink to &quot;Element&quot;">​</a></h3><p>One building block of a web page, written in HTML: a heading <code>&lt;h1&gt;</code>, a button, an input box. An element can have an <code>id</code>, a unique name that JavaScript uses to find it: <code>document.getElementById(&quot;add-button&quot;)</code>. If the id is misspelled, JavaScript gets <a href="#null">null</a>. <em>Week 0 onward; in depth in week 7.</em></p><h3 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h3><p>One specific address on a server or <a href="#api">API</a> that does one job, such as <code>/api/ask</code>. <em>Like one counter at a post office: this one takes parcels, that one sells stamps.</em> <em>Week 9.</em></p><h3 id="env-file" tabindex="-1">.env file <a class="header-anchor" href="#env-file" aria-label="Permalink to &quot;.env file&quot;">​</a></h3><p>A file that holds <a href="#environment-variable">environment variables</a>, usually secrets, for running your app on your own machine or Codespace. It is listed in <a href="#gitignore">.gitignore</a> so it is never committed. A companion file, <code>.env.example</code>, shows the variable names with placeholder values. <em>Week 9.</em></p><h3 id="environment-variable" tabindex="-1">Environment variable <a class="header-anchor" href="#environment-variable" aria-label="Permalink to &quot;Environment variable&quot;">​</a></h3><p>A named setting handed to a program from outside its code, such as <code>LLM_API_KEY</code>. It keeps secrets and settings out of your files: locally they come from <code>.env</code>, and on your host you type them into the dashboard. <em>Like a sealed envelope handed to the chef each morning, instead of writing the safe combination on the recipe card.</em> <em>Week 9.</em></p><h3 id="event-and-event-listener" tabindex="-1">Event and event listener <a class="header-anchor" href="#event-and-event-listener" aria-label="Permalink to &quot;Event and event listener&quot;">​</a></h3><p>An <em>event</em> is something that happens on the page: a click, a key press, the page finishing loading. An <em>event listener</em> is code that waits for one event and runs when it happens: <code>button.addEventListener(&quot;click&quot;, addBook)</code>. The function you hand over is a <a href="#callback">callback</a>. <em>Week 0 onward; in depth in week 7.</em></p><h3 id="exit-ticket" tabindex="-1">Exit ticket <a class="header-anchor" href="#exit-ticket" aria-label="Permalink to &quot;Exit ticket&quot;">​</a></h3><p>A three-question check, done with the AI off, once a week in weeks 1–14, usually at the end of <a href="#studio-a-and-studio-b">Studio B</a>. One question each week asks about the project from <em>two weeks earlier</em>, because remembering it later is what counts. Graded on completion, not correctness, as part of your Labs score. There are none in weeks 15–16. <em>Weeks 1–14.</em></p><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><h3 id="favicon" tabindex="-1">Favicon <a class="header-anchor" href="#favicon" aria-label="Permalink to &quot;Favicon&quot;">​</a></h3><p>The tiny icon in the browser tab next to your page&#39;s title. A small touch that makes a project look finished. <em>Week 15.</em></p><h3 id="fetch" tabindex="-1">fetch <a class="header-anchor" href="#fetch" aria-label="Permalink to &quot;fetch&quot;">​</a></h3><p>The built-in JavaScript function for sending an HTTP request, in the browser or in Node.js, such as <code>await fetch(&#39;/api/ask&#39;, { method: &#39;POST&#39;, body })</code>. It&#39;s how your page talks to your server, and how your server talks to an LLM provider. It returns a <a href="#promise">Promise</a>, so you <code>await</code> it. <em>Week 0; used from week 9.</em></p><h3 id="fork" tabindex="-1">Fork <a class="header-anchor" href="#fork" aria-label="Permalink to &quot;Fork&quot;">​</a></h3><p>Your own copy of someone else&#39;s repository, under your GitHub account. You can change it freely without affecting theirs. <em>Week 9.</em></p><h3 id="forwarded-port" tabindex="-1">Forwarded port <a class="header-anchor" href="#forwarded-port" aria-label="Permalink to &quot;Forwarded port&quot;">​</a></h3><p>In a <a href="#codespace">Codespace</a>, your app runs on a computer in the cloud. A forwarded <a href="#port">port</a> gives you a private web address that connects your browser to it. The <strong>Ports</strong> tab lists them. <em>Weeks 6–16.</em></p><h3 id="framework" tabindex="-1">Framework <a class="header-anchor" href="#framework" aria-label="Permalink to &quot;Framework&quot;">​</a></h3><p>A large ready-made toolkit for building apps in one particular style, such as React. App builders usually generate framework code. This course avoids frameworks so that every file stays short enough to read. <em>Week 5.</em></p><h3 id="free-tier" tabindex="-1">Free tier <a class="header-anchor" href="#free-tier" aria-label="Permalink to &quot;Free tier&quot;">​</a></h3><p>The no-cost level of a paid service, with limits such as messages per day or credits per month. Limits change often and are listed only in <a href="./../TOOLS.html">Tool Handout</a>. Running out is expected; you switch to the fallback (<a href="./troubleshooting.html#i-ran-out-of-free-credits">troubleshooting</a>). <em>Week 0 onward.</em></p><h3 id="front-end" tabindex="-1">Front end <a class="header-anchor" href="#front-end" aria-label="Permalink to &quot;Front end&quot;">​</a></h3><p>The parts of an app that run in the browser: HTML, CSS and JavaScript. Everything in the front end is public, including any key you put there. Compare <a href="#back-end">back end</a>. <em>Weeks 1 and 9.</em></p><h3 id="function" tabindex="-1">Function <a class="header-anchor" href="#function" aria-label="Permalink to &quot;Function&quot;">​</a></h3><p>A named, reusable block of code that does one job, as in Python. In JavaScript it&#39;s written <code>function countWords(text) { ... }</code> instead of <code>def count_words(text):</code>, or as an <a href="#arrow-function">arrow function</a>. A JavaScript function with no <code>return</code> gives back <a href="#undefined">undefined</a>, and calling it with too few arguments doesn&#39;t fail. Explaining any function you committed is one of the <a href="./without-ai-skills.html#2-explain-any-function-you-committed">six skills</a>. <em>Week 0 onward.</em></p><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><h3 id="gem" tabindex="-1">Gem <a class="header-anchor" href="#gem" aria-label="Permalink to &quot;Gem&quot;">​</a></h3><p>A custom assistant you set up inside Gemini with saved instructions, available on the free plan. The course&#39;s hint-only <a href="#tutor-mode">tutor</a> can be shared as a Gem. <em>Week 7.</em></p><h3 id="git" tabindex="-1">git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;git&quot;">​</a></h3><p>A program that records <a href="#commit">commits</a> of your project so you can see what changed, when, and go back. It runs on your computer or in your Codespace. See <a href="./git-cheatsheet.html">Git Cheat Sheet</a>. <em>Week 3.</em></p><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><p>A website that stores git <a href="#repository">repositories</a> online and adds tools around them: Pages, Codespaces, Copilot, <a href="#pull-request">pull requests</a>. In this course, GitHub is where all your work is saved, whatever tool made it. <em>Week 0 onward.</em></p><h3 id="github-actions" tabindex="-1">GitHub Actions <a class="header-anchor" href="#github-actions" aria-label="Permalink to &quot;GitHub Actions&quot;">​</a></h3><p>GitHub&#39;s automation: small jobs that run by themselves when something happens in a repository, such as publishing your GitHub Pages site after each push, or running tests. You can watch them in the repo&#39;s <strong>Actions</strong> tab. Running tests automatically like this is called <em>CI</em> (continuous integration). <em>Weeks 2 and 15.</em></p><h3 id="githubdev" tabindex="-1">github.dev <a class="header-anchor" href="#githubdev" aria-label="Permalink to &quot;github.dev&quot;">​</a></h3><p>A light version of VS Code that opens in the browser when you press the <code>.</code> key on a repository page. You can edit files and commit, but there is no terminal. <em>Week 3.</em></p><h3 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-label="Permalink to &quot;GitHub Pages&quot;">​</a></h3><p>GitHub&#39;s free hosting for <a href="#static-site">static sites</a> from a public repository. Your home page lives at <code>https://[username].github.io</code>. <em>Week 2.</em></p><h3 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h3><p>A file listing things git must never track, such as <code>.env</code>, <code>node_modules/</code> and <code>.DS_Store</code>. Adding a file here does <strong>not</strong> remove it from past commits. <em>Week 9.</em></p><h3 id="goldfish-test" tabindex="-1">Goldfish test <a class="header-anchor" href="#goldfish-test" aria-label="Permalink to &quot;Goldfish test&quot;">​</a></h3><p>Paste <strong>only</strong> your <code>SPEC.md</code> (or <code>AGENTS.md</code>) into a fresh chat, and ask what it would build and what it would need to ask you. If it can&#39;t understand or build from the document alone, revise the document, not the chat. <em>A goldfish remembers nothing, and neither does a fresh chat.</em> Prompt: <a href="./prompt-patterns.html#18-the-goldfish-test">Prompt Patterns: 18. The Goldfish test</a>. <em>Weeks 5 and 12.</em></p><h3 id="grace-token" tabindex="-1">Grace token <a class="header-anchor" href="#grace-token" aria-label="Permalink to &quot;Grace token&quot;">​</a></h3><p>One of the two 48-hour extensions each student can use on most deadlines without asking. The rules are in <a href="./../assessment/#late-work-and-grace-tokens">Assessment: Late work and grace tokens</a>.</p><h3 id="grant" tabindex="-1">Grant <a class="header-anchor" href="#grant" aria-label="Permalink to &quot;Grant&quot;">​</a></h3><p>In a database, a permission that lets a role use a table at all, such as <code>grant select on notes to authenticated</code>. In Supabase, <code>anon</code> is the role for anyone using your publishable key and <code>authenticated</code> is a signed-in user. From 30 October 2026, new Supabase tables start with no grants, so the API answers &quot;permission denied&quot; until you add one. A grant says <em>which roles may use a table</em>; <a href="#row-level-security-rls">row-level security</a> policies say <em>which rows</em>. Always add both together, and never answer &quot;permission denied&quot; with a bare grant to <code>anon</code> (<a href="./troubleshooting.html#permission-denied-for-a-new-table">how</a>). <em>Week 13.</em></p><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><h3 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h3><p>When an AI states something invented as if it were true: a function that doesn&#39;t exist, a package name nobody published, a test result that never happened. It sounds exactly as confident as a correct answer, which is why you verify. <em>Week 1.</em></p><h3 id="happy-path" tabindex="-1">Happy path <a class="header-anchor" href="#happy-path" aria-label="Permalink to &quot;Happy path&quot;">​</a></h3><p>The normal case, where the user does everything as expected. It&#39;s tempting to test only the happy path. Test <a href="#edge-case">edge cases</a> too. <em>Week 5.</em></p><h3 id="hard-reload" tabindex="-1">Hard reload <a class="header-anchor" href="#hard-reload" aria-label="Permalink to &quot;Hard reload&quot;">​</a></h3><p>A reload that ignores the <a href="#cache">cache</a> and fetches fresh files: <strong>Ctrl+Shift+R</strong> (Windows, Linux, ChromeOS) or <strong>Cmd+Shift+R</strong> (Mac). <em>Weeks 1–8.</em></p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>The program around an AI model that turns it into an <a href="#agent">agent</a>. It gives the model its tools, runs each <a href="#tool-call">tool call</a> the model asks for, and feeds the result back. In <em>Be the Agent</em>, one student plays the harness. <em>Week 11.</em></p><h3 id="hook" tabindex="-1">Hook <a class="header-anchor" href="#hook" aria-label="Permalink to &quot;Hook&quot;">​</a></h3><p>A script that runs automatically at a set moment. Three kinds matter here. (1) In a coding agent, a hook you configure runs before or after the agent&#39;s actions, and unlike a rules file it can actually <em>block</em> one. (2) In git, a <em>pre-commit</em> hook runs checks before each commit (they can be skipped with <code>--no-verify</code>, so they help but don&#39;t guarantee). (3) In npm, an install hook such as <code>preinstall</code> runs a package&#39;s code the moment you install it, which is how malicious packages strike (<a href="./case-studies.html#15-malware-that-hunts-for-ai-keys">case study 15</a>). Read any hook from someone else before you adopt it (<a href="./../setup/safety-contract.html">safety contract rule 7</a>). <em>Weeks 11–14.</em></p><h3 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h3><p>Short for <em>HyperText Markup Language</em>: the structure and content of a page, such as headings, paragraphs, buttons and images. <em>The walls and rooms of the house.</em> <em>Week 1.</em></p><h3 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h3><p>The rules browsers and servers use to talk. The browser sends a <strong>request</strong> (a method such as GET or POST, a URL, and sometimes a body), and the server sends back a <strong>response</strong> (a <a href="#status-code">status code</a>, and a body). HTTPS is the encrypted version. See <a href="./web-basics.html#requests-and-responses-http">How the Web Works: Requests and responses (HTTP)</a>. <em>Week 9.</em></p><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><h3 id="innerhtml-and-textcontent" tabindex="-1">innerHTML and textContent <a class="header-anchor" href="#innerhtml-and-textcontent" aria-label="Permalink to &quot;innerHTML and textContent&quot;">​</a></h3><p>Two ways JavaScript puts text on a page. <code>textContent</code> shows text exactly as typed. <code>innerHTML</code> treats it as HTML, so if a user types code, the browser may run it. For anything a user typed, use <code>textContent</code>; see <a href="#xss">XSS</a>. <em>Weeks 7 and 14.</em></p><h2 id="j" tabindex="-1">J <a class="header-anchor" href="#j" aria-label="Permalink to &quot;J&quot;">​</a></h2><h3 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h3><p>The programming language browsers run to make pages <em>do</em> things: react to clicks, save data, fetch from APIs. With <a href="#nodejs">Node.js</a> it also runs on servers. <em>The wiring and electricity of the house.</em> Not related to Java. Know Python? Start with <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward.</em></p><h3 id="json" tabindex="-1">JSON <a class="header-anchor" href="#json" aria-label="Permalink to &quot;JSON&quot;">​</a></h3><p>Short for <em>JavaScript Object Notation</em>: a plain-text format for structured data, such as <code>{&quot;name&quot;: &quot;Ada&quot;, &quot;score&quot;: 3}</code>. Most APIs send and receive JSON. It looks like a JavaScript <a href="#object">object</a> with quoted keys; <code>JSON.parse</code> and <code>JSON.stringify</code> are Python&#39;s <code>json.loads</code> and <code>json.dumps</code>. <em>Week 9.</em></p><h2 id="k" tabindex="-1">K <a class="header-anchor" href="#k" aria-label="Permalink to &quot;K&quot;">​</a></h2><h3 id="knowledge-cutoff" tabindex="-1">Knowledge cutoff <a class="header-anchor" href="#knowledge-cutoff" aria-label="Permalink to &quot;Knowledge cutoff&quot;">​</a></h3><p>The date a model&#39;s training data ends. The model knows nothing newer (new versions of tools, changed prices, recent events) unless you paste it into the chat, and it may confidently describe an old version as if it were current. <em>Week 1.</em></p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="let-and-const" tabindex="-1">let and const <a class="header-anchor" href="#let-and-const" aria-label="Permalink to &quot;let and const&quot;">​</a></h3><p>The two words that declare a variable in JavaScript; Python needs neither. <code>const</code> is for a name you never assign again, and <code>let</code> for one whose value changes, such as a counter. A <code>const</code> array can still change inside (<code>push</code> works); you just can&#39;t point the name at a new array. You&#39;ll also see <code>var</code>, an older form with confusing rules: ask the AI for <code>let</code> or <code>const</code> instead. See <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward.</em></p><h3 id="lethal-trifecta" tabindex="-1">Lethal trifecta <a class="header-anchor" href="#lethal-trifecta" aria-label="Permalink to &quot;Lethal trifecta&quot;">​</a></h3><p>Simon Willison&#39;s name for a dangerous combination in an AI agent: access to <strong>private data</strong>, exposure to <strong>untrusted content</strong>, and a <strong>way to send data out</strong>. An agent with all three can be tricked into leaking your data. Coding agents usually have all three. See <a href="#rule-of-two">Rule of Two</a>. <em>Week 14.</em></p><h3 id="live-preview" tabindex="-1">Live preview <a class="header-anchor" href="#live-preview" aria-label="Permalink to &quot;Live preview&quot;">​</a></h3><p>A chat assistant feature that runs the HTML, CSS and JavaScript it writes in a panel next to the chat, so you can see and click your page without saving any files. Gemini calls it <em>Canvas</em> (not the course&#39;s <a href="#canvas-lms">Canvas</a> website) and Claude calls it <em>Artifacts</em>; which to use is in <a href="./../TOOLS.html">Tool Handout</a>. <em>Weeks 1–4.</em></p><h3 id="llm" tabindex="-1">LLM <a class="header-anchor" href="#llm" aria-label="Permalink to &quot;LLM&quot;">​</a></h3><p>Short for <em>large language model</em>: an AI trained on huge amounts of text that writes text, including code, by predicting the next <a href="#token">token</a> over and over. It does not look anything up or run your code unless a tool lets it, and it can be confidently wrong (<a href="#hallucination">hallucination</a>). <em>Week 1.</em></p><h3 id="lms" tabindex="-1">LMS <a class="header-anchor" href="#lms" aria-label="Permalink to &quot;LMS&quot;">​</a></h3><p>Learning management system: your school&#39;s course website, where you submit work and see grades. This course uses <a href="#canvas-lms">Canvas</a>, which has nothing to do with Gemini&#39;s Canvas.</p><h3 id="localhost" tabindex="-1">localhost <a class="header-anchor" href="#localhost" aria-label="Permalink to &quot;localhost&quot;">​</a></h3><p>The address that means &quot;this computer&quot;, such as <code>http://localhost:3000</code>. A server you start in a Codespace listens on localhost, and Codespaces forwards it to a private web address you can open. <em>Weeks 6–10.</em></p><h3 id="localstorage" tabindex="-1">localStorage <a class="header-anchor" href="#localstorage" aria-label="Permalink to &quot;localStorage&quot;">​</a></h3><p>A small storage area in the browser where a page can save text that survives a reload. It exists only in that browser on that device, and anyone using the device can read it in DevTools → Application. Fine for a to-do list; never for secrets. <em>Weeks 3–8.</em></p><h3 id="lts" tabindex="-1">LTS <a class="header-anchor" href="#lts" aria-label="Permalink to &quot;LTS&quot;">​</a></h3><p>Long-term support: the version of a tool, such as Node.js, that gets fixes for years and is recommended for most people. Choose it in the optional <a href="./../setup/local-setup.html">local setup</a>.</p><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h3><p>A simple way to format plain text files that end in <code>.md</code>: <code>#</code> for a heading, <code>**bold**</code>, <code>-</code> for a list. Every page of this course, and every README, is Markdown. <em>Week 2.</em></p><h3 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h3><p>Short for <em>Model Context Protocol</em>: an open standard for connecting AI agents to tools and data, such as a database, a browser or a design app. <em>Like a universal plug that lets any agent use any tool.</em> An MCP server can run code on your machine, so read it before you install it. <em>Week 11.</em></p><h3 id="merge" tabindex="-1">Merge <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;Merge&quot;">​</a></h3><p>Combining the changes from one <a href="#branch">branch</a> into another. If both sides changed the same lines, git can&#39;t decide and asks you to resolve a <em>merge conflict</em> by hand (<a href="./troubleshooting.html#i-have-a-merge-conflict">how</a>). <em>Weeks 12–14.</em></p><h3 id="mock" tabindex="-1">Mock <a class="header-anchor" href="#mock" aria-label="Permalink to &quot;Mock&quot;">​</a></h3><p>A fake stand-in used in a test so the test doesn&#39;t depend on the outside world. The course&#39;s tests replace the real <code>fetch</code> with a mock that returns a made-up answer, so they run without internet access or an API key. <em>Weeks 9–11.</em></p><h3 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h3><p>One specific trained AI, such as the one behind a chat assistant. Companies release new models often and retire old ones, so the course names them only in <a href="./../TOOLS.html">Tool Handout</a>. <em>Week 1.</em></p><h3 id="model-id" tabindex="-1">Model ID <a class="header-anchor" href="#model-id" aria-label="Permalink to &quot;Model ID&quot;">​</a></h3><p>The exact name an AI provider uses for one model in API requests. IDs change often, so don&#39;t copy one from an old tutorial. In the week 9 starter, <code>npm run models</code> lists the IDs your key can use. <em>Week 9.</em></p><h3 id="module" tabindex="-1">Module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;Module&quot;">​</a></h3><p>A JavaScript file that shares some of its functions with other files using <code>export</code>, and uses theirs with <code>import</code>. The starters keep pure logic in modules under <code>public/lib/</code> so the same code runs in the browser and in tests. A page loads a module with <code>&lt;script type=&quot;module&quot;&gt;</code>, which only works when the page is served, not opened as a file. Unlike Python, a file must <code>export</code> what it shares. <em>Week 4 (your first test); the starters from week 9.</em></p><h3 id="multimodal" tabindex="-1">Multimodal <a class="header-anchor" href="#multimodal" aria-label="Permalink to &quot;Multimodal&quot;">​</a></h3><p>Describes an AI model that accepts more than text, such as images or audio. You can photograph a paper <a href="#wireframe">wireframe</a> and ask a multimodal assistant to build the page from it. <em>Week 5.</em></p><h3 id="mvp" tabindex="-1">MVP <a class="header-anchor" href="#mvp" aria-label="Permalink to &quot;MVP&quot;">​</a></h3><p>Minimum viable product: the smallest version of your idea that is actually useful to someone. Build it first, ship it, then add features. <em>Week 5.</em></p><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><h3 id="nan" tabindex="-1">NaN <a class="header-anchor" href="#nan" aria-label="Permalink to &quot;NaN&quot;">​</a></h3><p>&quot;Not a number&quot;: what JavaScript gives you when a calculation can&#39;t produce one, such as <code>Number(&quot;ten&quot;)</code> or <code>undefined + 1</code>. There&#39;s no error, and NaN spreads through every calculation it touches, so a total that shows <code>NaN</code> usually means one input was missing or was text. Check with <code>Number.isNaN(x)</code>. <em>Week 0 onward.</em></p><h3 id="nodejs" tabindex="-1">Node.js <a class="header-anchor" href="#nodejs" aria-label="Permalink to &quot;Node.js&quot;">​</a></h3><p>A program that runs JavaScript outside the browser: on a server, or in your Codespace terminal. The course&#39;s starters, servers and tests use it, on <strong>Node.js 22 LTS (minimum 20.12)</strong>. <em>Week 4 (tests); servers from week 9.</em></p><h3 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;npm&quot;">​</a></h3><p>The <em>Node package manager</em>: a command-line tool that installs <a href="#package">packages</a> and runs a project&#39;s scripts (<code>npm test</code>, <code>npm run dev</code>). Also the name of the public package registry at npmjs.com. <em>Week 5 onward.</em></p><h3 id="npx" tabindex="-1">npx <a class="header-anchor" href="#npx" aria-label="Permalink to &quot;npx&quot;">​</a></h3><p>A command that comes with <a href="#npm">npm</a> and runs a package&#39;s tool without installing it permanently, such as <code>npx --yes degit …</code>. It downloads and runs code, so check the package name first (see <a href="#slopsquatting">slopsquatting</a>). <em>Weeks 7–16.</em></p><h3 id="null" tabindex="-1">Null <a class="header-anchor" href="#null" aria-label="Permalink to &quot;Null&quot;">​</a></h3><p>JavaScript&#39;s value for &quot;deliberately empty&quot;. It&#39;s one of JavaScript&#39;s two versions of Python&#39;s <code>None</code>; the other is <a href="#undefined">undefined</a>. The browser returns <code>null</code> when you look for a page <a href="#element">element</a> that doesn&#39;t exist, so the error <code>Cannot read properties of null</code> usually means exactly that. <em>Week 0 onward; in depth in week 7.</em></p><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><h3 id="oauth" tabindex="-1">OAuth <a class="header-anchor" href="#oauth" aria-label="Permalink to &quot;OAuth&quot;">​</a></h3><p>The standard behind &quot;Sign in with GitHub&quot; or &quot;Sign in with Google&quot; buttons. You let one service use your account on another without giving it your password. Read what access you are granting before you click <strong>Authorize</strong>. <em>Weeks 6–10.</em></p><h3 id="object" tabindex="-1">Object <a class="header-anchor" href="#object" aria-label="Permalink to &quot;Object&quot;">​</a></h3><p>JavaScript&#39;s version of a Python dictionary: named values in curly braces, such as <code>{ title: &quot;Dune&quot;, pages: 412 }</code>. Read a value with a dot (<code>book.title</code>) or with brackets (<code>book[&quot;title&quot;]</code>). A missing key gives <a href="#undefined">undefined</a>, not a <code>KeyError</code>. <a href="#json">JSON</a> is written in the same shape. See <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward.</em></p><h3 id="openai-compatible-api" tabindex="-1">OpenAI-compatible API <a class="header-anchor" href="#openai-compatible-api" aria-label="Permalink to &quot;OpenAI-compatible API&quot;">​</a></h3><p>An <a href="#api">API</a> that accepts requests in the same format as OpenAI&#39;s &quot;chat completions&quot; API. Many providers offer one, so the course&#39;s starter switches providers by changing three environment variables (<code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code>, <code>LLM_MODEL</code>) and no code. <em>Weeks 9–10.</em></p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="package" tabindex="-1">Package <a class="header-anchor" href="#package" aria-label="Permalink to &quot;Package&quot;">​</a></h3><p>Ready-made code that someone published (for JavaScript, on npm) and your project can install. Also called a <em>dependency</em>. Installing a package means trusting a stranger&#39;s code to run on your machine, so check that it exists and is the one you meant (<a href="#slopsquatting">slopsquatting</a>). <em>Weeks 9 and 14.</em></p><h3 id="pair-programming" tabindex="-1">Pair programming <a class="header-anchor" href="#pair-programming" aria-label="Permalink to &quot;Pair programming&quot;">​</a></h3><p>Two people working on one task at one screen. The <em>driver</em> types; the <em>navigator</em> reads, asks questions and thinks ahead. Swap every 15 minutes or so. Several labs use it.</p><h3 id="passkey" tabindex="-1">Passkey <a class="header-anchor" href="#passkey" aria-label="Permalink to &quot;Passkey&quot;">​</a></h3><p>A replacement for a password: your device proves who you are with your fingerprint, face or PIN. Much harder to steal with <a href="#phishing">phishing</a>. Use one for GitHub and Google if you can. <em>Week 0.</em></p><h3 id="phishing" tabindex="-1">Phishing <a class="header-anchor" href="#phishing" aria-label="Permalink to &quot;Phishing&quot;">​</a></h3><p>A fake message or website that tricks you into typing a password, code or key. Before signing in anywhere, check the address bar, not the look of the page. <em>Week 0.</em></p><h3 id="plan-mode" tabindex="-1">Plan mode <a class="header-anchor" href="#plan-mode" aria-label="Permalink to &quot;Plan mode&quot;">​</a></h3><p>An agent setting in which it reads your files and proposes a plan but doesn&#39;t edit anything until you approve. In a chat assistant you get the same effect by saying &quot;Don&#39;t write any code yet.&quot; <em>Week 11.</em></p><h3 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;Policy&quot;">​</a></h3><p>A rule written for <a href="#row-level-security-rls">row-level security</a> that says which rows a request may read or change. A typical Supabase policy lets a signed-in user touch only rows where <code>auth.uid() = user_id</code>: &quot;your ID must match the row&#39;s owner&quot;. <em>Week 13.</em></p><h3 id="port" tabindex="-1">Port <a class="header-anchor" href="#port" aria-label="Permalink to &quot;Port&quot;">​</a></h3><p>A numbered &quot;door&quot; on a computer that a server listens on, such as 8000 or 3000. Codespaces <em>forwards</em> ports so you can open your running app in a browser tab. <em>Week 6.</em></p><h3 id="postgres" tabindex="-1">Postgres <a class="header-anchor" href="#postgres" aria-label="Permalink to &quot;Postgres&quot;">​</a></h3><p>PostgreSQL: a popular free <a href="#database">database</a> that stores data in tables of rows and columns and is queried with <a href="#sql">SQL</a>. Every Supabase project includes one. <em>Week 13.</em></p><h3 id="preview-deployment" tabindex="-1">Preview deployment <a class="header-anchor" href="#preview-deployment" aria-label="Permalink to &quot;Preview deployment&quot;">​</a></h3><p>A copy of your app that Vercel builds for one branch or pull request, at its own address with a random-looking part in the name. Use it to try a change before you merge. On the free plan, older preview deployments get deleted, and visitors may be asked to sign in to Vercel, so never submit one: submit your <a href="#production-url">production URL</a>. <em>Weeks 10–16.</em></p><h3 id="production" tabindex="-1">Production <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Production&quot;">​</a></h3><p>The real, live version of an app that real users rely on, as opposed to <em>development</em>, where you experiment. Keep them separate, and never give an agent production passwords or keys (<a href="./case-studies.html#4-replit-the-deleted-production-database">case study</a>). <em>Weeks 10–14.</em></p><h3 id="production-url" tabindex="-1">Production URL <a class="header-anchor" href="#production-url" aria-label="Permalink to &quot;Production URL&quot;">​</a></h3><p>The stable public address of your deployed app, usually <code>https://[project-name].vercel.app</code>. It always shows your latest production deployment, built from <code>main</code>. It&#39;s the address you submit, with a screenshot. Compare <a href="#preview-deployment">preview deployment</a>; <a href="./troubleshooting.html#production-url-or-preview-url">which is which</a>. <em>Weeks 10–16.</em></p><h3 id="promise" tabindex="-1">Promise <a class="header-anchor" href="#promise" aria-label="Permalink to &quot;Promise&quot;">​</a></h3><p>A JavaScript placeholder for a result that arrives later, such as the answer to a web request. <a href="#fetch">fetch</a> returns one straight away; write <code>await</code> in front to wait for the real value (<a href="#async-and-await">async and await</a>). If you see <code>Promise {&lt;pending&gt;}</code> where you expected data, an <code>await</code> is missing. <em>Week 0; used from week 9.</em></p><h3 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h3><p>What you type to an AI. This course writes prompts in four parts: <strong>Goal · Context · Constraints · Done when</strong>. See <a href="./prompt-patterns.html">Prompt Patterns</a>. <em>Week 1 onward; the four parts from week 3.</em></p><h3 id="prompt-injection" tabindex="-1">Prompt injection <a class="header-anchor" href="#prompt-injection" aria-label="Permalink to &quot;Prompt injection&quot;">​</a></h3><p>Instructions hidden in content an AI reads, such as a web page, a file, an issue or an email, that hijack it into doing something you didn&#39;t ask. The AI can&#39;t reliably tell your instructions from the text it is processing. <em>Like a forged note slipped into an assistant&#39;s in-tray: &quot;The boss says to send the files to this address.&quot;</em> <em>Week 14.</em></p><h3 id="promptsmd" tabindex="-1">PROMPTS.md <a class="header-anchor" href="#promptsmd" aria-label="Permalink to &quot;PROMPTS.md&quot;">​</a></h3><p>The file in every project where you log your key prompts, what the AI got wrong, and what you changed yourself. Template: <a href="./../templates/PROMPTS.html">PROMPTS.md template</a>. <em>Week 2 onward.</em></p><h3 id="proxy" tabindex="-1">Proxy <a class="header-anchor" href="#proxy" aria-label="Permalink to &quot;Proxy&quot;">​</a></h3><p>A server that passes requests along on someone else&#39;s behalf. Your week 9 server route is a small proxy: the browser asks your server, and your server asks the AI provider using the secret key the browser never sees. <em>Week 9.</em></p><h3 id="publishable-key" tabindex="-1">Publishable key <a class="header-anchor" href="#publishable-key" aria-label="Permalink to &quot;Publishable key&quot;">​</a></h3><p>Supabase&#39;s public key, starting <code>sb_publishable_</code> (it replaces the legacy <a href="#anon-key">anon key</a>). It is designed to sit in browser code, in your capstone&#39;s <code>public/config.js</code> with the project URL: not every key is a secret. It is safe <strong>only</strong> if <a href="#row-level-security-rls">row-level security</a> protects every table. A public key plus missing rules means a public database. <em>Week 13.</em></p><h3 id="pull-request" tabindex="-1">Pull request <a class="header-anchor" href="#pull-request" aria-label="Permalink to &quot;Pull request&quot;">​</a></h3><p>A request on GitHub to merge one <a href="#branch">branch</a> into another, usually a feature branch into <code>main</code>. Its page shows the whole <a href="#diff">diff</a> in the <strong>Files changed</strong> tab, lets people comment on single lines and approve, and keeps the discussion; nothing changes on <code>main</code> until someone clicks <strong>Merge</strong>. If a merged pull request turns out bad, its <strong>Revert</strong> button undoes it. On Vercel, each one also gets a <a href="#preview-deployment">preview deployment</a>. From week 12 every capstone feature goes through a pull request, and the week 14 peer review is a pull-request review. Often shortened to PR. How: <a href="./git-cheatsheet.html#branches-and-pull-requests">Git Cheat Sheet: Branches and pull requests</a>. <em>Weeks 12–14.</em></p><h3 id="pure-function" tabindex="-1">Pure function <a class="header-anchor" href="#pure-function" aria-label="Permalink to &quot;Pure function&quot;">​</a></h3><p>A <a href="#function">function</a> whose result depends only on its inputs and that changes nothing else: no page, no storage, no network. Pure functions are the easiest code to test, which is why the starter kits keep logic in <code>lib/</code> folders. <em>Weeks 4–6.</em></p><h3 id="push-and-pull" tabindex="-1">Push and pull <a class="header-anchor" href="#push-and-pull" aria-label="Permalink to &quot;Push and pull&quot;">​</a></h3><p><strong>Push</strong> sends your commits from your Codespace (or computer) up to GitHub. <strong>Pull</strong> brings down commits made elsewhere. A commit is saved only locally until you push. <em>Week 4.</em></p><h3 id="push-protection" tabindex="-1">Push protection <a class="header-anchor" href="#push-protection" aria-label="Permalink to &quot;Push protection&quot;">​</a></h3><p>A GitHub feature that blocks a push when it recognizes a known kind of <a href="#secret">secret</a>, such as some API keys, in your commits. Helpful, but it doesn&#39;t recognize every kind of key, so check yourself as well. <em>Weeks 9–10.</em></p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="rate-limit" tabindex="-1">Rate limit <a class="header-anchor" href="#rate-limit" aria-label="Permalink to &quot;Rate limit&quot;">​</a></h3><p>The most requests you may make in a period of time, such as per minute or per day. Go over it and the server answers <code>429 Too Many Requests</code>. Free tiers have tight limits, listed in <a href="./../TOOLS.html">Tool Handout</a>. <em>Week 9.</em></p><h3 id="readme" tabindex="-1">README <a class="header-anchor" href="#readme" aria-label="Permalink to &quot;README&quot;">​</a></h3><p>The front page of a repository (<code>README.md</code>): what the project is, how to use it, how to run it. GitHub shows it below the file list. Template: <a href="./../templates/PROJECT_README.html">PROJECT_README.md template</a>. <em>Weeks 2 and 15.</em></p><h3 id="redgreen-testing" tabindex="-1">Red/green testing <a class="header-anchor" href="#redgreen-testing" aria-label="Permalink to &quot;Red/green testing&quot;">​</a></h3><p>Write a test <strong>first</strong> and watch it fail (red), then change the code until it passes (green). The red step proves the test really checks something. It is the automated form of <a href="#check-first">check first</a>. <em>Weeks 4 and 6.</em></p><h3 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h3><p>A named, fixed version of your project on GitHub, such as <code>v1.0</code>, created from <strong>Releases</strong> on your repo page. It marks &quot;this is the version I shipped&quot;. Optional in this course.</p><h3 id="repository" tabindex="-1">Repository <a class="header-anchor" href="#repository" aria-label="Permalink to &quot;Repository&quot;">​</a></h3><p>A project folder tracked by git, including its full history of commits. On GitHub it has a web page. Usually shortened to <em>repo</em>. <em>Week 2.</em></p><h3 id="revert" tabindex="-1">Revert <a class="header-anchor" href="#revert" aria-label="Permalink to &quot;Revert&quot;">​</a></h3><p>Undoing a commit by making a <strong>new</strong> commit that does the opposite. History is kept, so you can always see what happened and undo the undo. It is the safe way to undo, unlike <em>reset</em>, which rewrites history. See <a href="./git-cheatsheet.html#revert-vs-reset">Git Cheat Sheet: Revert vs reset</a>. <em>Weeks 3, 4 and 8.</em></p><h3 id="revoke" tabindex="-1">Revoke <a class="header-anchor" href="#revoke" aria-label="Permalink to &quot;Revoke&quot;">​</a></h3><p>To cancel a key or token so it stops working. If a secret was ever committed, pasted into a chat or shown on screen, revoke it and create a new one before doing anything else. Deleting the file is not enough, because git history keeps it. <em>Weeks 9–10 and 14.</em></p><h3 id="row-level-security-rls" tabindex="-1">Row-level security (RLS) <a class="header-anchor" href="#row-level-security-rls" aria-label="Permalink to &quot;Row-level security (RLS)&quot;">​</a></h3><p>Database rules, called <em>policies</em>, that decide which rows each user may read or change. The database enforces them itself, whatever the browser asks for. In Supabase you must turn RLS on for every table and write policies, together with the table&#39;s <a href="#grant">grants</a>; tables an agent creates through the API start with RLS off. Missing RLS is how the Lovable and Moltbook leaks, and the 16,326 databases UpGuard found, happened (<a href="./case-studies.html">case studies</a>). With RLS on and no matching policy, a query returns zero rows rather than an error. <em>Like safe-deposit boxes in a bank vault: everyone walks into the same vault, but your key opens only your box.</em> <em>Week 13.</em></p><h3 id="rule-of-two" tabindex="-1">Rule of Two <a class="header-anchor" href="#rule-of-two" aria-label="Permalink to &quot;Rule of Two&quot;">​</a></h3><p>Meta&#39;s guideline for AI agents: in one session, an agent should have <strong>no more than two</strong> of (1) untrusted input, (2) access to private data or sensitive systems, and (3) the ability to change things or send data out. If it needs all three, a human approves its actions. See <a href="#lethal-trifecta">lethal trifecta</a>. <em>Week 14.</em></p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="safe-loop" tabindex="-1">Safe Loop <a class="header-anchor" href="#safe-loop" aria-label="Permalink to &quot;Safe Loop&quot;">​</a></h3><p>The course&#39;s six-step way of working with AI: <strong>Describe → Plan → Step → Test → Read → Commit</strong>, with two habits inside it: <a href="#check-first">check first</a> and <a href="#teach-back">teach back</a>. See <a href="./safe-loop.html">The Safe Loop</a>. <em>Week 3 onward.</em></p><h3 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h3><p>An isolated place where a program, especially an <a href="#agent">agent</a>, can work without reaching your real files, passwords or accounts. If it breaks something, only the sandbox is damaged. The course uses a <a href="#codespace">Codespace</a> as the sandbox. <em>Week 11.</em></p><h3 id="scoped-token" tabindex="-1">Scoped token <a class="header-anchor" href="#scoped-token" aria-label="Permalink to &quot;Scoped token&quot;">​</a></h3><p>A key or token limited to exactly the job it is for: one project, one kind of action, read-only where possible, ideally with an expiry date. If it leaks, or an agent finds it, the damage stays small. In 2026 an agent deleted a company&#39;s database with a broad token it found in an unrelated file (<a href="./case-studies.html#13-pocketos-a-nine-second-database-deletion">case study 13</a>). <a href="./../setup/safety-contract.html">Safety contract rule 4</a>: agents get only narrowly scoped tokens, kept outside the project folder. <em>Weeks 9–11.</em></p><h3 id="secret" tabindex="-1">Secret <a class="header-anchor" href="#secret" aria-label="Permalink to &quot;Secret&quot;">​</a></h3><p>Anything that grants access: API keys, passwords, access <a href="#token">tokens</a>, a Supabase <a href="#secret-key-service-role-key">secret key</a>, the contents of <code>.env</code>. Secrets never go in browser code, in git, or in an AI chat. <em>Week 9.</em></p><h3 id="secret-key-service-role-key" tabindex="-1">Secret key (service-role key) <a class="header-anchor" href="#secret-key-service-role-key" aria-label="Permalink to &quot;Secret key (service-role key)&quot;">​</a></h3><p>Supabase&#39;s server-only key, starting <code>sb_secret_</code>. It replaces the legacy <em>service_role</em> key (a long <code>eyJ…</code> key), which is deprecated by the end of 2026. It <strong>bypasses</strong> row-level security and can read or delete everything, like a master key. It lives only in server environment variables: never in front-end code or <code>config.js</code>, never committed, and never given to an agent. <em>Week 13.</em></p><h3 id="selector" tabindex="-1">Selector <a class="header-anchor" href="#selector" aria-label="Permalink to &quot;Selector&quot;">​</a></h3><p>The part of a CSS rule that picks which <a href="#element">elements</a> it applies to: <code>button</code> (every button), <code>#add</code> (the element with <code>id=&quot;add&quot;</code>), <code>.card</code> (every element with <code>class=&quot;card&quot;</code>). JavaScript uses the same selectors to find elements, as in <code>document.querySelector(&quot;#add&quot;)</code>, which returns <a href="#null">null</a> when nothing matches. <em>Week 0 onward; in depth in week 7.</em></p><h3 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h3><p>A program, and the computer it runs on, that waits for requests and sends back responses. Code on your server, and its environment variables, cannot be seen by the people using your site. Compare <a href="#client">client</a>. <em>Week 9.</em></p><h3 id="serverless-function" tabindex="-1">Serverless function <a class="header-anchor" href="#serverless-function" aria-label="Permalink to &quot;Serverless function&quot;">​</a></h3><p>A small piece of server code that the host runs only when a request arrives, so you don&#39;t manage a server machine. Vercel runs each file in your <code>api/</code> folder this way. <em>Like calling a taxi instead of owning a car.</em> <em>Week 10.</em></p><h3 id="slopsquatting" tabindex="-1">Slopsquatting <a class="header-anchor" href="#slopsquatting" aria-label="Permalink to &quot;Slopsquatting&quot;">​</a></h3><p>Publishing malware under package names that AI models tend to invent, then waiting for someone to install the made-up name the AI suggested. Defense: check every new package on npmjs.com before installing it. See <a href="./case-studies.html#10-slopsquatting-the-packages-that-dont-exist">case studies</a>. <em>Week 14.</em></p><h3 id="source-control-panel" tabindex="-1">Source Control panel <a class="header-anchor" href="#source-control-panel" aria-label="Permalink to &quot;Source Control panel&quot;">​</a></h3><p>The part of VS Code (and github.dev) where you see changed files, read their diffs, write a commit message and commit. Open it from the branching-lines icon in the left sidebar. See <a href="./git-cheatsheet.html">Git Cheat Sheet</a>. <em>Weeks 3–8.</em></p><h3 id="spec" tabindex="-1">Spec <a class="header-anchor" href="#spec" aria-label="Permalink to &quot;Spec&quot;">​</a></h3><p>A short document, <code>SPEC.md</code>, that says what you will build and how you&#39;ll know it works: problem, user, user stories, acceptance criteria, what&#39;s out of scope, and a wireframe. <em>The prompt for the whole project.</em> Template: <a href="./../templates/SPEC.html">SPEC.md template</a>. <em>Week 5.</em></p><h3 id="spending-cap" tabindex="-1">Spending cap <a class="header-anchor" href="#spending-cap" aria-label="Permalink to &quot;Spending cap&quot;">​</a></h3><p>A hard limit on how much a paid service may charge, after which it stops working instead of billing you more. Every key that can spend money should have one (<a href="./../setup/safety-contract.html">safety contract rule 4</a>), so a stolen key or a runaway agent can&#39;t run up a bill; stolen AI keys have cost people over $1,000 (<a href="./case-studies.html#15-malware-that-hunts-for-ai-keys">case study 15</a>). The course&#39;s free tiers stop at their limits; set a cap before you ever add a payment method. <em>Weeks 9–10.</em></p><h3 id="sql" tabindex="-1">SQL <a class="header-anchor" href="#sql" aria-label="Permalink to &quot;SQL&quot;">​</a></h3><p>Short for <em>Structured Query Language</em>: the language for creating database tables and asking them questions, such as <code>select * from notes</code>. Supabase uses Postgres, a popular database that speaks SQL. In week 13 you paste prepared SQL rather than write it from scratch. <em>Week 13.</em></p><h3 id="stack-trace" tabindex="-1">Stack trace <a class="header-anchor" href="#stack-trace" aria-label="Permalink to &quot;Stack trace&quot;">​</a></h3><p>The list of lines under an error message showing the chain of function calls that led to it, most recent first. The first line that points at one of <em>your</em> files is usually where to look (<a href="./without-ai-skills.html#1-read-an-error-message-and-find-the-failing-line">how to read one</a>). <em>Week 7.</em></p><h3 id="stage" tabindex="-1">Stage <a class="header-anchor" href="#stage" aria-label="Permalink to &quot;Stage&quot;">​</a></h3><p>To choose which changes go into your next <a href="#commit">commit</a>. In the Source Control panel, the <strong>+</strong> next to a file stages it; in the terminal, <code>git add</code> does the same. <em>Weeks 3–4.</em></p><h3 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h3><p>The information an app is holding right now: the list of items, which one is selected, whether it is loading. Many bugs are the page showing something different from the state. <em>Week 7.</em></p><h3 id="static-site" tabindex="-1">Static site <a class="header-anchor" href="#static-site" aria-label="Permalink to &quot;Static site&quot;">​</a></h3><p>A site made only of files (HTML, CSS, JavaScript, images) that are sent to the browser exactly as they are, with no server code of your own. GitHub Pages hosts static sites. <em>Week 2.</em></p><h3 id="status-code" tabindex="-1">Status code <a class="header-anchor" href="#status-code" aria-label="Permalink to &quot;Status code&quot;">​</a></h3><p>The three-digit number at the start of every HTTP response: <code>200</code> OK, <code>404</code> Not Found, <code>429</code> Too Many Requests, <code>500</code> server error, and so on. See <a href="./web-basics.html#status-codes-you-will-meet">How the Web Works: Status codes you will meet</a>. <em>Week 9.</em></p><h3 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;Streaming&quot;">​</a></h3><p>Sending an AI&#39;s reply in small pieces as it is generated, so the text appears word by word instead of all at once. A stretch goal in week 9.</p><h3 id="strict-equality" tabindex="-1">Strict equality <a class="header-anchor" href="#strict-equality" aria-label="Permalink to &quot;Strict equality&quot;">​</a></h3><p>Comparing with <code>===</code> (and <code>!==</code>), which is true only when both the type and the value match, as Python&#39;s <code>==</code> is. JavaScript&#39;s two-character <code>==</code> converts types first, so <code>&quot;5&quot; == 5</code> is <code>true</code>. Use <code>===</code> everywhere; changing a stray <code>==</code> is an easy fix to make by hand. For arrays and objects, <code>===</code> checks whether they are the <em>same</em> one, not whether their contents match. See <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward.</em></p><h3 id="string" tabindex="-1">String <a class="header-anchor" href="#string" aria-label="Permalink to &quot;String&quot;">​</a></h3><p>Text inside a program, written in quotes: <code>&quot;hello&quot;</code>. As in Python, except that <code>+</code> with a string and a number joins them as text: anything read from an input box is a string, so <code>&quot;10&quot; + 5</code> gives <code>&quot;105&quot;</code>, not <code>15</code>, until you convert with <code>Number(...)</code>. JavaScript&#39;s f-string is the <a href="#template-literal">template literal</a>. <em>Week 0 onward.</em></p><h3 id="studio-a-and-studio-b" tabindex="-1">Studio A and Studio B <a class="header-anchor" href="#studio-a-and-studio-b" aria-label="Permalink to &quot;Studio A and Studio B&quot;">​</a></h3><p>The course&#39;s two 75-minute classes each week, in weeks 1–15. <strong>Studio A (Learn &amp; build):</strong> a recap, a short concept talk, a live demo and the core of the lab. <strong>Studio B (Workshop):</strong> show and tell, the rest of the lab or a second skill, project time and the exit ticket. Week 16 is finals week, with the final presentations instead. Each week&#39;s <code>lab.md</code> has a section for each. See the <a href="./../SYLLABUS.html#course-outline">syllabus</a>. <em>Weeks 1–15.</em></p><h3 id="syntaxerror-typeerror-and-referenceerror" tabindex="-1">SyntaxError, TypeError and ReferenceError <a class="header-anchor" href="#syntaxerror-typeerror-and-referenceerror" aria-label="Permalink to &quot;SyntaxError, TypeError and ReferenceError&quot;">​</a></h3><p>Three JavaScript errors you will meet. <strong>SyntaxError:</strong> the code is not valid JavaScript (often a missing bracket), so none of the file runs. <strong>TypeError:</strong> a value is the wrong kind for what the code tried, such as reading a property of <a href="#null">null</a>. <strong>ReferenceError:</strong> a name that was never defined, often a typo (Python&#39;s <code>NameError</code>). The Console shows each with a file and line number. <em>Week 0 onward; in depth in week 7.</em></p><h3 id="system-prompt" tabindex="-1">System prompt <a class="header-anchor" href="#system-prompt" aria-label="Permalink to &quot;System prompt&quot;">​</a></h3><p>Instructions given to a model before the conversation starts, setting its role and rules. Users usually don&#39;t see it. In your week 9 app it&#39;s the message with the role <code>&quot;system&quot;</code>; the <a href="./tutor-mode.html">course tutor</a> is a system prompt too. It is not a security wall: <a href="#prompt-injection">prompt injection</a> can override it. <em>Weeks 9–11.</em></p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="teach-back" tabindex="-1">Teach-back <a class="header-anchor" href="#teach-back" aria-label="Permalink to &quot;Teach-back&quot;">​</a></h3><p>Two or three sentences you write in <code>PROMPTS.md</code>, in your own words and with the AI off, before you commit AI-written code: what changed, why it works, and what you&#39;d check first if it broke. If you can&#39;t write it, you&#39;re not ready to commit. From week 11 it&#39;s graded in the capstone Process row. See <a href="./safe-loop.html#teach-back">The Safe Loop: Teach back</a>. <em>Week 3 onward; graded from week 11.</em></p><h3 id="telemetry" tabindex="-1">Telemetry <a class="header-anchor" href="#telemetry" aria-label="Permalink to &quot;Telemetry&quot;">​</a></h3><p>Usage data an app sends back to its maker, such as which features you used and what errors happened. Most tools let you turn some of it off. <em>Week 0.</em></p><h3 id="template-literal" tabindex="-1">Template literal <a class="header-anchor" href="#template-literal" aria-label="Permalink to &quot;Template literal&quot;">​</a></h3><p>A JavaScript string written in backticks, with values dropped in using <code>${...}</code>: <code>`Hello, ${name}!`</code>. It&#39;s JavaScript&#39;s version of Python&#39;s f-string, and it can span several lines. <em>Week 0 onward.</em></p><h3 id="template-repository" tabindex="-1">Template repository <a class="header-anchor" href="#template-repository" aria-label="Permalink to &quot;Template repository&quot;">​</a></h3><p>A GitHub repository set up as a starting point: its <strong>Use this template</strong> button makes a fresh copy under your account, with its own history. The course publishes its starter kits this way (<a href="./../setup/codespaces.html#start-a-project-from-a-starter">how to start from a starter</a>). <em>Weeks 7–11.</em></p><h3 id="temporary-chat" tabindex="-1">Temporary chat <a class="header-anchor" href="#temporary-chat" aria-label="Permalink to &quot;Temporary chat&quot;">​</a></h3><p>A chat mode that isn&#39;t saved to your history and, in most tools, isn&#39;t used for training. Use one for anything sensitive. See <a href="./../setup/privacy-settings.html">privacy settings</a>. <em>Week 0.</em></p><h3 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal&quot;">​</a></h3><p>A text window where you type commands, such as <code>git status</code> or <code>npm test</code>, and read their output. In a Codespace it is the panel at the bottom of the screen. Also called the <em>command line</em> or <em>shell</em>. <em>Weeks 0 and 4.</em></p><h3 id="test-manual-and-automated" tabindex="-1">Test (manual and automated) <a class="header-anchor" href="#test-manual-and-automated" aria-label="Permalink to &quot;Test (manual and automated)&quot;">​</a></h3><p>A check that the code does what it should. A <strong>manual test</strong> is a list of steps a person follows and a result to expect (<a href="./../templates/TESTS.html">TESTS.md template</a>). An <strong>automated test</strong> is code that checks code, run with <code>npm test</code>, so you can re-check everything in seconds after each change. <em>Manual: from week 5. Automated: from week 4.</em></p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Two meanings; context tells you which. (1) A chunk of text, often part of a word, that an <a href="#llm">LLM</a> reads and writes; context windows and limits are counted in tokens. (2) An <em>access token</em>: a secret string that works like a password for programs, such as a GitHub token. <em>Weeks 1 and 9.</em></p><h3 id="tool-call" tabindex="-1">Tool call <a class="header-anchor" href="#tool-call" aria-label="Permalink to &quot;Tool call&quot;">​</a></h3><p>A request from an AI model to its <a href="#harness">harness</a> to use one tool, such as &quot;read this file&quot; or &quot;run the tests&quot;. The harness runs it and sends back the result, and the model decides what to do next. <em>Week 11.</em></p><h3 id="truthy-and-falsy" tabindex="-1">Truthy and falsy <a class="header-anchor" href="#truthy-and-falsy" aria-label="Permalink to &quot;Truthy and falsy&quot;">​</a></h3><p>How JavaScript treats a value in an <code>if</code>. The <strong>falsy</strong> values are <code>false</code>, <code>0</code>, <code>&quot;&quot;</code>, <code>null</code>, <code>undefined</code> and <a href="#nan">NaN</a>; everything else is <strong>truthy</strong>. Unlike Python, an empty array <code>[]</code> and an empty object <code>{}</code> count as true, so test for an empty list with <code>items.length === 0</code>. <em>Week 0 onward.</em></p><h3 id="try-and-catch" tabindex="-1">try and catch <a class="header-anchor" href="#try-and-catch" aria-label="Permalink to &quot;try and catch&quot;">​</a></h3><p>JavaScript&#39;s way to handle an error, like Python&#39;s <code>try</code> and <code>except</code>: the code in <code>try { ... }</code> runs, and if it throws an error, the <code>catch (error) { ... }</code> block runs instead. <code>throw new Error(&quot;…&quot;)</code> raises one, like Python&#39;s <code>raise</code>. Many JavaScript mistakes throw nothing at all (they quietly produce <a href="#undefined">undefined</a> or <a href="#nan">NaN</a>), so <code>try</code> is no substitute for tests. <em>Week 0 onward.</em></p><h3 id="tutor-mode" tabindex="-1">Tutor mode <a class="header-anchor" href="#tutor-mode" aria-label="Permalink to &quot;Tutor mode&quot;">​</a></h3><p>Using an AI that gives hints and asks questions instead of handing you the answer. You switch it on by pasting the <a href="./tutor-mode.html">course tutor prompt</a>. It&#39;s the only AI allowed in the Debug Clinic. Working on your own? See <a href="./self-paced.html#using-tutor-mode">Self-Paced Path: Using tutor mode</a>. <em>Week 7.</em></p><h3 id="two-factor-authentication-2fa" tabindex="-1">Two-factor authentication (2FA) <a class="header-anchor" href="#two-factor-authentication-2fa" aria-label="Permalink to &quot;Two-factor authentication (2FA)&quot;">​</a></h3><p>A second check when you sign in, such as a code from an authenticator app or a <a href="#passkey">passkey</a>, on top of your password. Turn it on for GitHub and Google in week 0.</p><h3 id="two-strikes-rule" tabindex="-1">Two-strikes rule <a class="header-anchor" href="#two-strikes-rule" aria-label="Permalink to &quot;Two-strikes rule&quot;">​</a></h3><p>If two attempts to fix the same problem fail, stop. Go back to your last good commit if things got worse, start a fresh chat, and rewrite the prompt with what you learned. See <a href="./safe-loop.html#the-two-strikes-rule">The Safe Loop: The two-strikes rule</a>. <em>Week 3.</em></p><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h2><h3 id="undefined" tabindex="-1">Undefined <a class="header-anchor" href="#undefined" aria-label="Permalink to &quot;Undefined&quot;">​</a></h3><p>JavaScript&#39;s value for &quot;never given a value&quot;: a variable declared without one, a property an object doesn&#39;t have, the result of a function that returns nothing. It&#39;s one of JavaScript&#39;s two versions of Python&#39;s <code>None</code>; the other is <a href="#null">null</a>. A typo in a property name gives <code>undefined</code> instead of an error, so the problem often shows up far from the real mistake. See <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a>. <em>Week 0 onward.</em></p><h3 id="url" tabindex="-1">URL <a class="header-anchor" href="#url" aria-label="Permalink to &quot;URL&quot;">​</a></h3><p>A web address, such as <code>https://ada.github.io/game/index.html</code>. It names the protocol, the site and the file or <a href="#endpoint">endpoint</a>. See <a href="./web-basics.html#urls">How the Web Works: URLs</a>. <em>Weeks 1–2.</em></p><h3 id="user-story" tabindex="-1">User story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User story&quot;">​</a></h3><p>One sentence describing what someone wants and why: <em>As a …, I want to …, so that ….</em> Each story gets one or more <a href="#acceptance-criterion">acceptance criteria</a>. <em>Week 5.</em></p><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="variable" tabindex="-1">Variable <a class="header-anchor" href="#variable" aria-label="Permalink to &quot;Variable&quot;">​</a></h3><p>A name that holds a value, as in Python. JavaScript needs a keyword the first time: <code>let score = 0</code> or <code>const name = &quot;Ada&quot;</code> (see <a href="#let-and-const">let and const</a>). <em>Week 0 onward.</em></p><h3 id="vercel" tabindex="-1">Vercel <a class="header-anchor" href="#vercel" aria-label="Permalink to &quot;Vercel&quot;">​</a></h3><p>A hosting service that serves static files and runs <a href="#serverless-function">serverless functions</a>. The course&#39;s primary host from week 10. Its free plan can&#39;t deploy <strong>private</strong> repositories owned by a GitHub organization, so keep your project in a repo under your own username (<a href="./../TOOLS.html">Tool Handout</a>). Each deploy has a <a href="#production-url">production URL</a> or a <a href="#preview-deployment">preview deployment</a> address. <em>Week 10.</em></p><h3 id="vibe-coding" tabindex="-1">Vibe coding <a class="header-anchor" href="#vibe-coding" aria-label="Permalink to &quot;Vibe coding&quot;">​</a></h3><p>Andrej Karpathy&#39;s February 2025 name for building software by describing what you want to an AI, accepting whatever it writes without reading the code, and judging only by running it. Fine for throwaway toys. This course starts there in week 1, then adds <a href="#safe-loop">the Safe Loop</a>. Some authors now use the phrase for careful work as well, so check what a writer means. <em>Week 1.</em></p><h3 id="vs-code" tabindex="-1">VS Code <a class="header-anchor" href="#vs-code" aria-label="Permalink to &quot;VS Code&quot;">​</a></h3><p>Visual Studio Code, a free code editor from Microsoft. Codespaces and github.dev run it in your browser. <em>Week 4.</em></p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="wireframe" tabindex="-1">Wireframe <a class="header-anchor" href="#wireframe" aria-label="Permalink to &quot;Wireframe&quot;">​</a></h3><p>A rough sketch of a screen&#39;s layout: boxes and labels, no colors. Paper and a pen are fine. It goes in your <a href="#spec">spec</a>. <em>Week 5.</em></p><h3 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h3><p>Windows Subsystem for Linux: a way to run a Linux terminal inside Windows. Optional; only for the <a href="./../setup/local-setup.html">local setup</a>.</p><h2 id="x" tabindex="-1">X <a class="header-anchor" href="#x" aria-label="Permalink to &quot;X&quot;">​</a></h2><h3 id="xss" tabindex="-1">XSS <a class="header-anchor" href="#xss" aria-label="Permalink to &quot;XSS&quot;">​</a></h3><p>Short for <em>cross-site scripting</em>: an attacker gets their own JavaScript to run in other people&#39;s browsers, usually by typing code into a field that your page later displays with <code>innerHTML</code>. Prevent it by showing user text with <code>textContent</code>. Test with the input <code>&lt;img src=x onerror=alert(1)&gt;</code>: if an alert pops up, you have an XSS bug. <em>Week 14.</em></p>',423)])])}const p=a(s,[["render",n]]);export{m as __pageData,p as default};
